import { describe, it, expect } from '@jest/globals';
import { MockRegistry } from '../mocks/registry';

describe('MockRegistry Debug Test', () => {
  it('should have MockRegistry exported', () => {
    expect(MockRegistry).toBeDefined();
  });

  it('should have openai property', () => {
    expect(MockRegistry.openai).toBeDefined();
  });

  it('should have openai.create method', () => {
    expect(MockRegistry.openai.create).toBeDefined();
    expect(typeof MockRegistry.openai.create).toBe('function');
  });

  it('should create mock openai instance', () => {
    const instance = MockRegistry.openai.create();
    expect(instance).toBeDefined();
    expect(instance.chat).toBeDefined();
    expect(instance.chat.completions).toBeDefined();
    expect(instance.chat.completions.create).toBeDefined();
  });

  it('should have openai.chat method', () => {
    expect(MockRegistry.openai.chat).toBeDefined();
    expect(typeof MockRegistry.openai.chat).toBe('function');
  });

  it('should have openai.embedding method', () => {
    expect(MockRegistry.openai.embedding).toBeDefined();
    expect(typeof MockRegistry.openai.embedding).toBe('function');
  });
});